import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { findChrome, ChromeVisualBrowser } from './scratch/archify/archify/bin/visual-check.mjs';

async function main() {
  const chromePath = findChrome();
  console.log('Using Chrome binary:', chromePath);

  const htmlPath = path.resolve('.archify/architecture-ephapticos-runtime-20261011-073425/ephapticos-runtime.html');
  const fileUrl = pathToFileURL(htmlPath).href;
  console.log('Loading diagram from:', fileUrl);

  const browser = new ChromeVisualBrowser(chromePath);
  try {
    const session = await browser.sessionPromise;
    const send = (method, params = {}) => browser.cdp.send(method, params, session);

    // Set viewport to 2400 x 1260
    await send('Emulation.setDeviceMetricsOverride', {
      width: 2400,
      height: 1260,
      deviceScaleFactor: 1,
      mobile: false,
    });

    await send('Page.enable');
    await send('DOM.enable');

    await send('Page.navigate', { url: fileUrl });

    // Wait for page load
    await new Promise(r => setTimeout(r, 2000));

    // Evaluate in page
    const run = async (expr) => {
      const res = await send('Runtime.evaluate', {
        expression: expr,
        awaitPromise: true,
        returnByValue: true,
      });
      if (res.exceptionDetails) {
        throw new Error(res.exceptionDetails.exception?.description || 'Evaluation error');
      }
      return res.result?.value;
    };

    console.log('--- 1. VERIFY COMPONENT SEARCH ---');
    // Test searching / focusing component 'api_gateway'
    const searchResult1 = await run(`
      (() => {
        // Test search finder or direct focus
        const set1 = Archify.focus.set('api_gateway', { toggle: false, updateUrl: false });
        const active1 = Archify.focus.active();
        return { success: set1, activeNodes: active1 };
      })()
    `);
    console.log('Component search/focus for "api_gateway":', searchResult1);

    // Test searching / focusing component 'dataset_queue'
    const searchResult2 = await run(`
      (() => {
        const set2 = Archify.focus.set('dataset_queue', { toggle: false, updateUrl: false });
        const active2 = Archify.focus.active();
        return { success: set2, activeNodes: active2 };
      })()
    `);
    console.log('Component search/focus for "dataset_queue":', searchResult2);

    console.log('--- 2. VERIFY UPSTREAM & DOWNSTREAM TRACING ---');
    // Test downstream reach from 'api_gateway'
    const downstreamResult = await run(`
      (() => {
        Archify.focus.set('api_gateway', { toggle: false, updateUrl: false });
        const reachSuccess = Archify.focus.reach('downstream', { toggle: false, updateUrl: false, reveal: false });
        const snapshot = Archify.focus.reachabilitySnapshot();
        return {
          success: reachSuccess,
          direction: snapshot?.direction,
          nodeCount: snapshot?.nodeIds?.length,
          nodeIds: snapshot?.nodeIds,
          maxDepth: snapshot?.maxDepth
        };
      })()
    `);
    console.log('Downstream tracing from "api_gateway":', downstreamResult);

    // Test upstream reach from 'graph_db'
    const upstreamResult = await run(`
      (() => {
        Archify.focus.set('graph_db', { toggle: false, updateUrl: false });
        const reachSuccess = Archify.focus.reach('upstream', { toggle: false, updateUrl: false, reveal: false });
        const snapshot = Archify.focus.reachabilitySnapshot();
        return {
          success: reachSuccess,
          direction: snapshot?.direction,
          nodeCount: snapshot?.nodeIds?.length,
          nodeIds: snapshot?.nodeIds,
          maxDepth: snapshot?.maxDepth
        };
      })()
    `);
    console.log('Upstream tracing from "graph_db":', upstreamResult);

    // Clear reach and focus for clean export
    await run(`
      (() => {
        Archify.focus.clearReach({ updateUrl: false });
        Archify.focus.clear({ updateUrl: false });
      })()
    `);

    console.log('--- 3. EXPORT HIGH-RESOLUTION 2400 x 1260 PNG ---');
    const screenshot = await send('Page.captureScreenshot', {
      format: 'png',
      clip: {
        x: 0,
        y: 0,
        width: 2400,
        height: 1260,
        scale: 1,
      },
    });

    const pngBuffer = Buffer.from(screenshot.data, 'base64');
    const pngPath = path.resolve('.archify/architecture-ephapticos-runtime-20261011-073425/ephapticos-runtime.2400x1260.png');
    fs.writeFileSync(pngPath, pngBuffer);
    console.log(`Saved 2400x1260 PNG to ${pngPath} (${pngBuffer.length} bytes)`);

    const resultSummary = {
      searchWorking: searchResult1.success && searchResult2.success,
      downstreamTracingWorking: downstreamResult.success && downstreamResult.nodeCount > 0,
      upstreamTracingWorking: upstreamResult.success && upstreamResult.nodeCount > 0,
      pngExported: fs.existsSync(pngPath),
      pngBytes: pngBuffer.length,
      pngPath,
      downstreamNodes: downstreamResult.nodeIds,
      upstreamNodes: upstreamResult.nodeIds
    };

    console.log('FINAL VERIFICATION SUMMARY:', JSON.stringify(resultSummary, null, 2));

  } finally {
    await browser.close();
  }
}

main().catch(err => {
  console.error('Error in verification:', err);
  process.exit(1);
});

